select '48512d94-959c-5a94-b985-7e1bd005c6b7 unique profile' check_name,((with candidates as(select ep.id,case ep.scope when 'LEAF' then 4 when 'PROBLEM' then 3 when 'EXAM' then 2 else 1 end rank from public.math_subproblems l join public.math_problems pr on pr.id=l.problem_id join public.math_problem_sets ps on ps.id=pr.problem_set_id join public.math_evaluation_profiles ep on ep.state='ACTIVE' and ep.response_format=l.response_format and (ep.leaf_id=l.id or ep.problem_id=l.problem_id or ep.essay_exam_id=ps.essay_exam_id or (ep.scope='COMMON_MATH_RUBRIC' and l.allow_common_rubric)) where l.id='b5c82f4d-fb81-5d04-b0b1-3af5369379f1' and pr.state='ACTIVE' and ps.state='ACTIVE') select count(*)=1 and bool_and(id='b624884a-78da-5158-baf9-1873e73b86d2'::uuid) from candidates where rank=(select max(rank) from candidates))) passed
